// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// List the clusters registered to the current organization
	// (GET /api/clusters)
	ListClusters(ctx context.Context, request ListClustersRequestObject) (ListClustersResponseObject, error)
	// Register a Kubernetes cluster in the current organization
	// (POST /api/clusters)
	CreateCluster(ctx context.Context, request CreateClusterRequestObject) (CreateClusterResponseObject, error)
	// Delete a cluster
	// (DELETE /api/clusters/{id})
	DeleteCluster(ctx context.Context, request DeleteClusterRequestObject) (DeleteClusterResponseObject, error)
	// Get a cluster
	// (GET /api/clusters/{id})
	GetCluster(ctx context.Context, request GetClusterRequestObject) (GetClusterResponseObject, error)
	// Update a cluster (name and/or credentials)
	// (PATCH /api/clusters/{id})
	UpdateCluster(ctx context.Context, request UpdateClusterRequestObject) (UpdateClusterResponseObject, error)
	// Report the cluster credentials' access (capabilities)
	// (GET /api/clusters/{id}/capabilities)
	ListClusterCapabilities(ctx context.Context, request ListClusterCapabilitiesRequestObject) (ListClusterCapabilitiesResponseObject, error)
	// Generate an RBAC manifest for selected capabilities
	// (POST /api/clusters/{id}/capabilities/rbac)
	GenerateClusterRbac(ctx context.Context, request GenerateClusterRbacRequestObject) (GenerateClusterRbacResponseObject, error)
	// List the Kubernetes namespaces of a cluster
	// (GET /api/clusters/{id}/namespaces)
	ListClusterNamespaces(ctx context.Context, request ListClusterNamespacesRequestObject) (ListClusterNamespacesResponseObject, error)
	// List the Kubernetes nodes of a cluster
	// (GET /api/clusters/{id}/nodes)
	ListClusterNodes(ctx context.Context, request ListClusterNodesRequestObject) (ListClusterNodesResponseObject, error)
	// List the Kubernetes pods of a cluster
	// (GET /api/clusters/{id}/pods)
	ListClusterPods(ctx context.Context, request ListClusterPodsRequestObject) (ListClusterPodsResponseObject, error)
	// Re-probe a cluster's connectivity
	// (POST /api/clusters/{id}/test)
	TestCluster(ctx context.Context, request TestClusterRequestObject) (TestClusterResponseObject, error)
	// Liveness probe
	// (GET /api/health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// List pending invitations for the current organization (admins only)
	// (GET /api/invitations)
	ListInvitations(ctx context.Context, request ListInvitationsRequestObject) (ListInvitationsResponseObject, error)
	// Invite a user to the current organization (admins only)
	// (POST /api/invitations)
	CreateInvitation(ctx context.Context, request CreateInvitationRequestObject) (CreateInvitationResponseObject, error)
	// Revoke a pending invitation (admins only)
	// (DELETE /api/invitations/{id})
	RevokeInvitation(ctx context.Context, request RevokeInvitationRequestObject) (RevokeInvitationResponseObject, error)
	// Preview an invitation by its token
	// (GET /api/invites/{token})
	GetInvitation(ctx context.Context, request GetInvitationRequestObject) (GetInvitationResponseObject, error)
	// Accept an invitation and join its organization
	// (POST /api/invites/{token}/accept)
	AcceptInvitation(ctx context.Context, request AcceptInvitationRequestObject) (AcceptInvitationResponseObject, error)
	// The current user and their organization memberships
	// (GET /api/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// List the members of the current organization
	// (GET /api/members)
	ListMembers(ctx context.Context, request ListMembersRequestObject) (ListMembersResponseObject, error)
	// Remove a member from the organization (admins only)
	// (DELETE /api/members/{userId})
	RemoveMember(ctx context.Context, request RemoveMemberRequestObject) (RemoveMemberResponseObject, error)
	// Change a member's role (admins only)
	// (PATCH /api/members/{userId})
	UpdateMemberRole(ctx context.Context, request UpdateMemberRoleRequestObject) (UpdateMemberRoleResponseObject, error)
	// Create an organization (the caller becomes its first admin)
	// (POST /api/organizations)
	CreateOrganization(ctx context.Context, request CreateOrganizationRequestObject) (CreateOrganizationResponseObject, error)
	// Rename an organization (admins only)
	// (PATCH /api/organizations/{id})
	RenameOrganization(ctx context.Context, request RenameOrganizationRequestObject) (RenameOrganizationResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

